from functools import lru_cache

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    def decorator(func):
        if maxsize <= 0:
            raise ValueError('maxsize must be a positive integer')
        if ttl <= 0:
            raise ValueError('ttl must be a positive integer')

        @lru_cache(maxsize=maxsize)
        def wrapper(*args, **kwargs):
            cache_key = tuple(args) + tuple(sorted(kwargs.items()))
            if cache_key not in wrapper.cache:
                wrapper.cache.add(cache_key)
            wrapper.timecache = {cache_key: timer()}

            result = func(*args, **kwargs)
            wrapper.timecache.update({cache_key: timer()})

            ttl_elapsed = wrapper.timecache[cache_key] - wrapper.timecache[cache_key] - ttl
            if ttl_elapsed > 0:
                del wrapper.cache[cache_key]

            return result

        # Lazyinitialize cache set to avoid AttributeError
        wrapper.cache = set()
        wrapper.timecache = {}

        return wrapper

    return decorator
