from collections.abc import Mapping

def difference(d1, d2, level=-1):
    if level != -1 and isinstance(d1, Mapping) and isinstance(d2, Mapping):
        if level == 0 or not next(iter(d1)):
            return {k: v for k, v in d1.items() if k not in d2}
        else:
            return {
                k: difference(d1[k], d2.get(k, {}), level - 1)
                for k in d1 if k not in d2
            } | {k: d2[k] for k in d2 if k not in d1}
    else:
        return {k: v for k, v in (d1 | d2).items() if k not in d2}
