def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not extract_spec_version and not 'type' in inventory:
        raise ArgumentError("Inventory missing required 'type' component",)

    if not 'type' in inventory or not isinstance(inventory['type'], type):
        inventory_type = inventory.get('type', None)
        raise ArgumentError("Expected type spec item '{0}' to be an instance of 'type', got {1}".format(
            'type', inventory_type))

    if 'type' in inventory:
        if extract_spec_version:
            inventory_version = inventory['type']
        else:
            inventory_version = self.spec_version

        if isinstance(inventory_version, types.FunctionType):
            inventory_version = inventory_version()

        if inventory_version not in {1, 2, 3, 4, 5}:
            raise ArgumentError("Expected inventory version to be one of 1 through 5, got {0}".format(
                inventory_version))

    for key, value in inventory.items():
        if key == 'type':
            continue

        if not isinstance(value, (list, type, set)):
            raise ArgumentError("Expected all items in inventory to be of type 'type', 'list', or 'set', got {0}.".format(
                type(value)))

    return inventory
