    etc.) does not completely replace the corresponding section in a merged file.
    """
    merged_nodes = {}
    # Helper function to recursively deep merge values
    def _deep_merge(source, target):
        if isinstance(source, MappingNode):
            target = MappingNode()
            for key, value in source.items():
                if key in target:
                    _deep_merge(value, target[key])
                else:
