from typing import List, Optional

class Node:
    pass

class Graph:
    def __init__(self):
        self.nodes = set()
        self.edges = set()

    def add_node(self, node: Node):
        self.nodes.add(node)

    def add_edge(self, edge: "Edge"):
        self.edges.add(edge)
        if edge.from_node not in self.nodes:
            self.nodes.add(edge.from_node)
        if edge.to_node not in self.nodes:
            self.nodes.add(edge.to_node)

    def get_parents(self, node: Node) -> set:
        return {edge.from_node for edge in self.edges if edge.to_node == node}

class Edge:
    def __init__(self, from_node: Node, to_node: Node):
        self.from_node = from_node
        self.to_node = to_node

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if roots is None:
        roots = set()

    queue = deque()
    for node in graph.nodes:
        if graph.get_parents(node).isdisjoint(roots):
            queue.append(node)
            roots.add(node)
            break

    while queue:
        node = queue.popleft()
        parents = graph.get_parents(node)
        for parent in parents:
            if parent not in roots:
                queue.append(parent)
                roots.add(parent)

    return roots
