class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.queue = []
        self.cache = {}
        self.queue_set = set()

    def _turn_lru(self, key):
        if key in self.queue_set:
            self.queue_set.remove(key)
        self.queue_set.add(key)
        idx = self.queue.index(key)
        self.queue.pop(idx)
        self.queue.insert(0, key)
        return key

    def popitem(self):
        """Remove and return the `(key, value)` pair least recently used."""

        if len(self.cache) > self.capacity:
            key_pop = self._turn_lru(self.queue[-1])
            del self.cache[key_pop]

        return (self.queue[0], self.cache.pop(self.queue[0]))
